{"implementation":"import math


def _require_number(value, field):
    if isinstance(value, bool) or not isinstance(value, (int, float)):
        raise ValueError(f"{field} must be a number")
    value = float(value)
    if not math.isfinite(value):
        raise ValueError(f"{field} must be finite")
    return value


def solve(case):
    if not isinstance(case, dict):
        raise ValueError("case must be an object")
    if "threshold" not in case or "calls" not in case:
        raise ValueError("case requires threshold and calls")

    threshold = _require_number(case["threshold"], "threshold")
    calls = case["calls"]
    if not isinstance(calls, list):
        raise ValueError("calls must be an array")

    accepted_call_ids = []
    diagnostics = []
    required = (
        "call_id",
        "loss_without_call",
        "loss_with_call",
        "prediction_tokens",
        "parseable",
    )

    for index, call in enumerate(calls):
        if not isinstance(call, dict):
            raise ValueError(f"calls[{index}] must be an object")
        missing = [field for field in required if field not in call]
        if missing:
            raise ValueError(f"calls[{index}] missing required field: {missing[0]}")

        call_id = call["call_id"]
        if not isinstance(call_id, str):
            raise ValueError(f"calls[{index}].call_id must be a string")
        loss_without = _require_number(
            call["loss_without_call"], f"calls[{index}].loss_without_call"
        )
        loss_with = _require_number(
            call["loss_with_call"], f"calls[{index}].loss_with_call"
        )
        prediction_tokens = call["prediction_tokens"]
        if (
            isinstance(prediction_tokens, bool)
            or not isinstance(prediction_tokens, int)
            or prediction_tokens < 0
        ):
            raise ValueError(
                f"calls[{index}].prediction_tokens must be a non-negative integer"
            )
        parseable = call["parseable"]
        if not isinstance(parseable, bool):
            raise ValueError(f"calls[{index}].parseable must be a boolean")

        gain = loss_without - loss_with
        normalized_gain = gain / max(1, prediction_tokens)
        accepted = parseable and gain > 0 and normalized_gain >= threshold
        rounded_gain = round(normalized_gain, 8)

        if accepted:
            accepted_call_ids.append(call_id)
        diagnostics.append(
            {
                "accepted": accepted,
                "call_id": call_id,
                "normalized_gain": rounded_gain,
            }
        )

    return {
        "accepted_call_ids": accepted_call_ids,
        "diagnostics": diagnostics,
    }
